const cmds = [
  ["lifecycle-working", ["sed","-n","760,940p","cmd/entire/cli/lifecycle.go"]],
  ["strategy-working", ["sed","-n","3030,3225p","cmd/entire/cli/strategy/manual_commit_hooks.go"]],
  ["lifecycle-ours", ["git","show",":2:cmd/entire/cli/lifecycle.go"]],
  ["lifecycle-theirs", ["git","show",":3:cmd/entire/cli/lifecycle.go"]],
  ["strategy-ours", ["git","show",":2:cmd/entire/cli/strategy/manual_commit_hooks.go"]],
  ["strategy-theirs", ["git","show",":3:cmd/entire/cli/strategy/manual_commit_hooks.go"]]
];
const results = await Promise.all(cmds.map(async ([name, argv]) => {
  const max = name.includes("working") ? 12000 : 50000;
  const r = await tools.exec_command({cmd: argv.map(x => JSON.stringify(x)).join(" "), workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-claude-transcript-readiness", yield_time_ms:30000, max_output_tokens:max});
  return [name, r.output];
}));
for (const [name, output] of results) {
  if (name === "lifecycle-ours") store("lifecycle_ours", output);
  else if (name === "lifecycle-theirs") store("lifecycle_theirs", output);
  else if (name === "strategy-ours") store("strategy_ours", output);
  else if (name === "strategy-theirs") store("strategy_theirs", output);
  else { text(`## ${name}\n${output}`); }
}

